// ═══ SYNCHRONIZED METHOD — locks 'this' for entire method ═══
public class AccountService {
    private BigDecimal balance = new BigDecimal("100000");

    public synchronized void debit(BigDecimal amount) {
        // Lock acquired on 'this' (the AccountService instance)
        validateAmount(amount);          // locked — even though no shared state!
        logTransaction(amount);          // locked — even though no shared state!
        balance = balance.subtract(amount); // THIS is the only line that needs sync!
        notifyAudit(amount);             // locked — even though no shared state!
        // Lock released when method exits
    }
    // Problem: validateAmount, logTransaction, notifyAudit don't need the lock!
    // Other threads calling ANY synchronized method on this object are BLOCKED!
}

// ═══ SYNCHRONIZED BLOCK — locks specific object for specific code ═══
public class AccountService {
    private BigDecimal balance = new BigDecimal("100000");
    private final Object balanceLock = new Object();  // dedicated lock object

    public void debit(BigDecimal amount) {
        validateAmount(amount);          // NOT locked — runs freely!
        logTransaction(amount);          // NOT locked — runs freely!

        synchronized (balanceLock) {     // lock ONLY for critical section!
            balance = balance.subtract(amount);
        }

        notifyAudit(amount);             // NOT locked — runs freely!
    }
    // Only balance modification is locked! Everything else runs in parallel!
}

// ═══ LOCK OBJECT CHOICES ═══
// synchronized method:        locks on 'this'
// synchronized(this):         same as synchronized method
// synchronized(lockObject):   locks on specific object — BEST! Granular control.
// synchronized(ClassName.class): class-level lock (like static synchronized)

// ═══ STATIC SYNCHRONIZED — locks on Class object ═══
public static synchronized void globalOperation() {
    // Locks on AccountService.class — ALL instances blocked!
}
// Equivalent to:
public static void globalOperation() {
    synchronized (AccountService.class) { /* ... */ }
}

// ═══ WHY BLOCK IS PREFERRED ═══
// 1. Shorter lock time: only critical section is locked
// 2. Specific lock: different operations can use different locks
// 3. Multiple locks: balanceLock for balance, auditLock for audit log
// 4. Lock on final object: prevents lock reassignment bugs
// 5. Better concurrency: non-critical code runs in parallel
