// ─── File: src/test/java/com/bank/sync/SyncMethodVsBlockTest.java ───
package com.bank.sync;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import static org.assertj.core.api.Assertions.*;

class SyncMethodVsBlockTest {

    // ═══ Synchronized METHOD: blocks entire object ═══
    static class CoarseLockAccount {
        BigDecimal balance = new BigDecimal("100000");

        synchronized void debit(BigDecimal amount) throws InterruptedException {
            Thread.sleep(100);  // simulates slow validation
            balance = balance.subtract(amount);
        }

        synchronized BigDecimal getBalance() {
            return balance;  // blocked while debit() is running!
        }
    }

    // ═══ Synchronized BLOCK: locks only critical section ═══
    static class FineLockAccount {
        BigDecimal balance = new BigDecimal("100000");
        private final Object balanceLock = new Object();

        void debit(BigDecimal amount) throws InterruptedException {
            Thread.sleep(100);  // validation runs WITHOUT lock!
            synchronized (balanceLock) {
                balance = balance.subtract(amount);  // only THIS is locked!
            }
        }

        BigDecimal getBalance() {
            synchronized (balanceLock) {
                return balance;  // NOT blocked by debit's sleep()!
            }
        }
    }

    @Test
    void coarseLock_getBalanceBlockedDuringDebit() throws Exception {
        CoarseLockAccount account = new CoarseLockAccount();
        AtomicBoolean debitStarted = new AtomicBoolean(false);

        Thread debiter = new Thread(() -> {
            try {
                debitStarted.set(true);
                account.debit(new BigDecimal("1000"));
            } catch (InterruptedException e) { }
        });
        debiter.start();
        Thread.sleep(50);  // let debit start (and hold lock during sleep)

        // getBalance is BLOCKED because debit holds the lock!
        long start = System.currentTimeMillis();
        account.getBalance();
        long elapsed = System.currentTimeMillis() - start;
        debiter.join();

        // getBalance had to wait ~50ms for debit to finish!
        assertThat(elapsed).isGreaterThanOrEqualTo(30);
    }

    @Test
    void fineLock_getBalanceNotBlockedDuringValidation() throws Exception {
        FineLockAccount account = new FineLockAccount();

        Thread debiter = new Thread(() -> {
            try { account.debit(new BigDecimal("1000")); }
            catch (InterruptedException e) { }
        });
        debiter.start();
        Thread.sleep(50);  // debit is in sleep() — NOT holding lock!

        // getBalance is NOT blocked — lock only held during subtract!
        long start = System.currentTimeMillis();
        account.getBalance();
        long elapsed = System.currentTimeMillis() - start;
        debiter.join();

        assertThat(elapsed).isLessThan(20);  // instant! Not blocked!
    }

    @Test
    void threadSafety_withSyncBlock() throws Exception {
        FineLockAccount account = new FineLockAccount();
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                try { account.debit(new BigDecimal("1000")); }
                catch (InterruptedException e) { }
                latch.countDown();
            }).start();
        }

        latch.await();
        assertThat(account.getBalance()).isEqualByComparingTo("0");  // thread-safe!
    }
}
